const triggerData = $('Meeting Router Call').first().json;
const useCaseItems = $('Query Use Case Library').all();

const useCasesSerialized = useCaseItems.map(item => {
  const j = item.json;
  const name = j['Use case'] || j.name || 'Unknown';
  const slug = j['Slug'] || j.slug || '';
  const vertical = j['Vertical'] || '';
  const fn = j['Function'] || '';
  const headline = j['CEO headline'] || '';
  const outcome = j['Outcome / KPI'] || '';
  return `- [${slug}] ${name} (Vertical: ${vertical}, Function: ${fn})\n  Business value: ${headline}\n  Outcome: ${outcome}`;
}).join('\n');

// Use newly created Slack channel ID if one was auto-created this execution
let slackChannelId;
try {
  slackChannelId = $('Create Company Channel').first().json.id;
} catch(e) {
  slackChannelId = triggerData.slackChannelId || '';
}

const userPrompt = `CLIENT: ${triggerData.companyName} (${triggerData.companyIndustry})\nDEAL: ${triggerData.dealName} — ${triggerData.dealStage} — ${triggerData.dealType}\nCONTACT: ${triggerData.contactName}, ${triggerData.contactRole}\nCALL SUMMARY: ${triggerData.lastCallSummary}\nGIST: ${triggerData.gist}\nTOPICS DISCUSSED: ${Array.isArray(triggerData.topicsDiscussed) ? triggerData.topicsDiscussed.join(', ') : triggerData.topicsDiscussed}\nACTION ITEMS: ${Array.isArray(triggerData.actionItems) ? triggerData.actionItems.join('; ') : triggerData.actionItems}\n\nAVAILABLE USE CASES FROM OUR LIBRARY:\n${useCasesSerialized}\n\nBased on the discovery call, select the 2-4 most relevant use cases from our library and generate:\n\nReturn valid JSON with this exact structure:\n{\n  "selectedUseCases": [\n    { "slug": "use-case-slug", "name": "Use case name", "relevanceReason": "Why this applies to the client" }\n  ],\n  "executiveSummary": "2-3 paragraph executive summary of the engagement opportunity",\n  "engagementTitle": "Short title for this engagement (e.g. AI Automation for [Company] — Phase 1)",\n  "scope": "Detailed scope of work: what Novagentica will deliver, what is out of scope",\n  "deliverables": ["Deliverable 1", "Deliverable 2"],\n  "timeline": "Proposed timeline (e.g. 12-week phased delivery: Week 1-2 Discovery, Week 3-6 Build, Week 7-10 Test, Week 11-12 Go-live)",\n  "assumptions": ["Key assumption 1", "Key assumption 2"],\n  "engagementType": "Ingestion or Build or Hybrid",\n  "nextSteps": "3-4 immediate next steps to advance this deal"\n}\nReturn only valid JSON.`;

return [{
  json: {
    userPrompt,
    meetingId: triggerData.meetingId,
    meetingDate: triggerData.meetingDate,
    companyId: triggerData.companyId,
    companyName: triggerData.companyName,
    companyIndustry: triggerData.companyIndustry,
    dealId: triggerData.dealId,
    dealName: triggerData.dealName,
    dealStage: triggerData.dealStage,
    contactName: triggerData.contactName,
    contactEmail: triggerData.contactEmail,
    transcriptUrl: triggerData.transcriptUrl,
    slackChannelId,
    gDriveFolderUrl: triggerData.gDriveFolderUrl
  }
}];

const claudeItem = $('Generate Proposal with Claude').first().json;
const promptItem = $('Prepare Claude Prompt').first().json;

let rawText = claudeItem.text || claudeItem.output || '';

let parsed;
try {
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in Claude response');
  }
} catch (e) {
  parsed = {
    selectedUseCases: [{ slug: 'general-ai', name: 'General AI Automation', relevanceReason: 'Broad automation needs identified' }],
    executiveSummary: 'Executive summary to be refined.',
    engagementTitle: 'AI Automation for ' + promptItem.companyName + ' — Phase 1',
    scope: 'Scope to be defined.',
    deliverables: ['AI Agent Design', 'Integration & Testing', 'Go-Live Support'],
    timeline: '12-week phased delivery',
    assumptions: ['Client provides data access', 'Stakeholders available for workshops'],
    engagementType: 'Build',
    nextSteps: 'Schedule scoping workshop, agree on data access, align on timeline.'
  };
}

const selectedUseCasesText = (parsed.selectedUseCases || [])
  .map(uc => '• ' + uc.name + ': ' + uc.relevanceReason)
  .join('\n');

const deliverablesText = (parsed.deliverables || [])
  .map((d, i) => (i + 1) + '. ' + d)
  .join('\n');

const assumptionsText = (parsed.assumptions || [])
  .map((a, i) => (i + 1) + '. ' + a)
  .join('\n');

const selectedUseCaseNames = (parsed.selectedUseCases || [])
  .map(uc => uc.name)
  .join(', ');

const sowContent = `STATEMENT OF WORK\n\nClient: ${promptItem.companyName}\nEngagement: ${parsed.engagementTitle}\nPrepared by: Novagentica\nDate: ${promptItem.meetingDate}\n\nEXECUTIVE SUMMARY\n${parsed.executiveSummary}\n\nSELECTED USE CASES\n${selectedUseCasesText}\n\nSCOPE OF WORK\n${parsed.scope}\n\nDELIVERABLES\n${deliverablesText}\n\nTIMELINE\n${parsed.timeline}\n\nKEY ASSUMPTIONS\n${assumptionsText}\n\nNEXT STEPS\n${parsed.nextSteps}`;

return [{
  json: {
    engagementTitle: parsed.engagementTitle,
    executiveSummary: parsed.executiveSummary,
    scope: parsed.scope,
    deliverables: parsed.deliverables,
    deliverablesText,
    timeline: parsed.timeline,
    assumptions: parsed.assumptions,
    assumptionsText,
    engagementType: parsed.engagementType || 'Build',
    nextSteps: parsed.nextSteps,
    selectedUseCases: parsed.selectedUseCases,
    selectedUseCasesText,
    selectedUseCaseNames,
    sowContent,
    companyId: promptItem.companyId,
    companyName: promptItem.companyName,
    dealId: promptItem.dealId,
    contactName: promptItem.contactName,
    contactEmail: promptItem.contactEmail,
    transcriptUrl: promptItem.transcriptUrl,
    slackChannelId: promptItem.slackChannelId,
    gDriveFolderUrl: promptItem.gDriveFolderUrl,
    meetingDate: promptItem.meetingDate,
    dealStage: promptItem.dealStage
  }
}];

const parsedData = $('Parse Claude Response').first().json;
const docData = $('Create SoW Document').first().json;
const slidesData = $('Create Pitch Deck').first().json;

const sowDocId = docData.id || '';
const sowUrl = sowDocId ? 'https://docs.google.com/document/d/' + sowDocId + '/edit' : '';

const deckId = slidesData.presentationId || slidesData.id || '';
const deckUrl = deckId ? 'https://docs.google.com/presentation/d/' + deckId + '/edit' : '';

return [{
  json: {
    ...parsedData,
    sowDocId,
    sowUrl,
    deckId,
    deckUrl
  }
}];

const docData = $('Combine Document URLs').first().json;
const notionData = $('Create Notion Project').first().json;

const notionProjectUrl = notionData.url || 'https://notion.so';
const slackChannelId = docData.slackChannelId || 'D0B3KBGM2CQ';

const slackMessage = ':page_facing_up: *Proposal generated for ' + docData.companyName + '*\n' +
  '*Engagement:* ' + docData.engagementTitle + '\n' +
  '*Contact:* ' + docData.contactName + '\n' +
  '*Deal stage:* ' + docData.dealStage + '\n\n' +
  '*Documents generated:*\n' +
  '• <' + docData.sowUrl + '|Statement of Work>\n' +
  '• <' + docData.deckUrl + '|Pitch Deck>\n' +
  '• <' + notionProjectUrl + '|Notion Project>\n\n' +
  '*Selected use cases:* ' + docData.selectedUseCaseNames + '\n\n' +
  'Approve to send to client?';

return [{
  json: {
    slackChannelId,
    slackMessage,
    notionProjectUrl,
    ...docData
  }
}];
